parameters.jsCode:
const memoria = $getWorkflowStaticData('global');

if (!memoria.eventosD1) {
  memoria.eventosD1 = {};
}

const nuevos = [];

for (const item of $input.all()) {
  const dato = item.json;

  const consulta = String(dato.query ?? '');
  const filas = Number(dato.rows ?? 0);
  const llamadas = Number(dato.calls ?? 0);

  // Cada combinación identifica un estado de la consulta.
  const identificador = JSON.stringify({
    consulta,
    filas,
    llamadas
  });

  if (memoria.eventosD1[identificador]) {
    continue;
  }

  memoria.eventosD1[identificador] = true;
  nuevos.push(item);
}

return nuevos;
